import MessageScrollerProvider from "@marko-ui/shadcn/ui/message-scroller/message-scroller-provider.marko";
import MessageScroller from "@marko-ui/shadcn/ui/message-scroller/message-scroller.marko";
import MessageScrollerViewport from "@marko-ui/shadcn/ui/message-scroller/viewport.marko";
import MessageScrollerContent from "@marko-ui/shadcn/ui/message-scroller/content.marko";
import MessageScrollerItem from "@marko-ui/shadcn/ui/message-scroller/item.marko";
import MessageScrollerButton from "@marko-ui/shadcn/ui/message-scroller/button.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardHeader from "@marko-ui/shadcn/ui/card/header.marko";
import CardTitle from "@marko-ui/shadcn/ui/card/title.marko";
import CardDescription from "@marko-ui/shadcn/ui/card/description.marko";
import CardAction from "@marko-ui/shadcn/ui/card/action.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import CardFooter from "@marko-ui/shadcn/ui/card/footer.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";
import Empty from "@marko-ui/shadcn/ui/empty/empty.marko";
import EmptyHeader from "@marko-ui/shadcn/ui/empty/header.marko";
import EmptyMedia from "@marko-ui/shadcn/ui/empty/media.marko";
import EmptyTitle from "@marko-ui/shadcn/ui/empty/title.marko";
import EmptyDescription from "@marko-ui/shadcn/ui/empty/description.marko";
import Message from "@marko-ui/shadcn/ui/message/message.marko";
import MessageContent from "@marko-ui/shadcn/ui/message/content.marko";
import Bubble from "@marko-ui/shadcn/ui/bubble/bubble.marko";
import BubbleContent from "@marko-ui/shadcn/ui/bubble/bubble-content.marko";
import Tooltip from "@marko-ui/shadcn/ui/tooltip/tooltip.marko";

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  text: string;
}

static const SCRIPT: ChatMessage[] = [
  {
    id: "demo-1-user",
    role: "user",
    text: "I'm building a chat for our app and the scroll behavior is driving me nuts. Every time the AI streams a reply, the whole thread jumps around.",
  },
  {
    id: "demo-1-assistant",
    role: "assistant",
    text: "That's the classic streaming scroll problem. Wrap your message list in MessageScroller and turn on autoScroll — the viewport pins to the bottom as tokens arrive, so users always see the latest text land in place.\n\nIt only auto-scrolls while the reader is already at the bottom. The moment they scroll up, auto-scroll backs off and their position is preserved.",
  },
  {
    id: "demo-2-user",
    role: "user",
    text: "Okay, but when someone sends a new message the view still feels jarring — like the whole conversation reloads from the top.",
  },
  {
    id: "demo-2-assistant",
    role: "assistant",
    text: "MessageScrollerItem fixes that with turn anchoring. Set scrollAnchor on the turn that should settle near the top instead of blindly snapping to the document bottom.\n\nIt also leaves a small peek of the previous exchange visible above the anchor, so context isn't lost.",
  },
  {
    id: "demo-3-user",
    role: "user",
    text: "And if they've scrolled up to re-read an older answer? I don't want to yank them back down.",
  },
  {
    id: "demo-3-assistant",
    role: "assistant",
    text: "You won't. Auto-scroll only runs when the viewport is already pinned to the bottom, so scrolling up is a deliberate opt-out. When there is content they haven't seen, MessageScrollerButton appears — one tap jumps them back and re-engages auto-scroll.",
  },
];

<let/messages=([] as ChatMessage[])/>
<let/busy=false/>
<const/nextMessage=SCRIPT[messages.length]/>

<const/send=() => {
  if (!nextMessage || busy) return;
  const outgoing = nextMessage;
  messages = [...messages, outgoing];
  if (outgoing.role === "user") {
    busy = true;
    setTimeout(() => {
      const reply = SCRIPT[messages.length];
      if (reply) messages = [...messages, reply];
      busy = false;
    }, 700);
  }
}/>

<const/reset=() => {
  messages = [];
  busy = false;
}/>

<MessageScrollerProvider|controller| autoScroll>
  <div class="relative flex flex-col gap-4">
    <Card class="mx-auto h-140 w-full max-w-sm gap-0">
      <CardHeader class="gap-1 border-b">
        <CardTitle>New Chat</CardTitle>
        <CardDescription>How can I help you today?</CardDescription>
        <CardAction>
          <Tooltip>
            <@trigger|props|>
              <Button type="button" ...props variant="outline" size="icon" aria-label="Reset conversation" disabled=busy onClick=reset>
                <Icon name="RotateCwIcon"/>
              </Button>
            </@trigger>
            Reset
          </Tooltip>
        </CardAction>
      </CardHeader>
      <CardContent class="flex-1 overflow-hidden p-0">
        <if=(messages.length === 0)>
          <Empty class="h-full">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <Icon name="MessageCircleIcon"/>
              </EmptyMedia>
              <EmptyTitle>Morning, shadcn!</EmptyTitle>
              <EmptyDescription>
                What are we working on today? Press send to start a new conversation
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        </if>
        <else>
          <MessageScroller controller=controller>
            <MessageScrollerViewport controller=controller>
              <MessageScrollerContent controller=controller aria-busy=(busy ? "true" : "false") class="p-4">
                <for|message| of=messages by=(message) => message.id>
                  <MessageScrollerItem controller=controller messageId=message.id scrollAnchor=(message.role === "user")>
                    <Message align=(message.role === "user" ? "end" : "start")>
                      <MessageContent>
                        <Bubble variant=(message.role === "user" ? "muted" : "ghost")>
                          <BubbleContent class="space-y-2">
                            <for|paragraph| of=message.text.split(/\n\s*\n/)>
                              <p class="whitespace-pre-wrap">${paragraph}</p>
                            </for>
                          </BubbleContent>
                        </Bubble>
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                </for>
              </MessageScrollerContent>
            </MessageScrollerViewport>
            <MessageScrollerButton controller=controller/>
          </MessageScroller>
        </else>
      </CardContent>
      <CardFooter class="flex-col gap-2">
        <div class="flex h-14 w-full items-center rounded-md border border-input px-3 py-2.5 text-sm">
          <if=nextMessage>
            <span class=("line-clamp-2 " + (busy ? "opacity-60" : ""))>${nextMessage.text}</span>
          </if>
          <else>
            <span class="text-muted-foreground">No messages queued. Reset the conversation.</span>
          </else>
          <Button
            type="button"
            size="icon-sm"
            class="ml-auto shrink-0"
            disabled=(!nextMessage || busy)
            onClick=send
          >
            <Icon name="ArrowUpIcon"/>
            <span class="sr-only">Send</span>
          </Button>
        </div>
      </CardFooter>
    </Card>
    <div class="px-0.5 text-center text-xs text-muted-foreground">
      Demo is read only. Press send to send messages.
    </div>
  </div>
</MessageScrollerProvider>

import MessageScrollerProvider from "@marko-ui/shadcn/ui/message-scroller/message-scroller-provider.marko";
import MessageScroller from "@marko-ui/shadcn/ui/message-scroller/message-scroller.marko";
import MessageScrollerViewport from "@marko-ui/shadcn/ui/message-scroller/viewport.marko";
import MessageScrollerContent from "@marko-ui/shadcn/ui/message-scroller/content.marko";
import MessageScrollerItem from "@marko-ui/shadcn/ui/message-scroller/item.marko";
import MessageScrollerButton from "@marko-ui/shadcn/ui/message-scroller/button.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardHeader from "@marko-ui/shadcn/ui/card/header.marko";
import CardTitle from "@marko-ui/shadcn/ui/card/title.marko";
import CardDescription from "@marko-ui/shadcn/ui/card/description.marko";
import CardAction from "@marko-ui/shadcn/ui/card/action.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import CardFooter from "@marko-ui/shadcn/ui/card/footer.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";
import Empty from "@marko-ui/shadcn/ui/empty/empty.marko";
import EmptyHeader from "@marko-ui/shadcn/ui/empty/header.marko";
import EmptyMedia from "@marko-ui/shadcn/ui/empty/media.marko";
import EmptyTitle from "@marko-ui/shadcn/ui/empty/title.marko";
import EmptyDescription from "@marko-ui/shadcn/ui/empty/description.marko";
import Message from "@marko-ui/shadcn/ui/message/message.marko";
import MessageContent from "@marko-ui/shadcn/ui/message/content.marko";
import Bubble from "@marko-ui/shadcn/ui/bubble/bubble.marko";
import BubbleContent from "@marko-ui/shadcn/ui/bubble/bubble-content.marko";
import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

export type AnchorRole = "user" | "assistant";

export interface ChatMessage {
  id: string;
  role: AnchorRole;
  text: string;
}

static const SCRIPT: ChatMessage[] = [
  { id: "anchor-1-user", role: "user", text: "Can you show me how anchoring behaves when a new prompt starts the turn?" },
  { id: "anchor-1-assistant", role: "assistant", text: "Append the user prompt first, then append the assistant response. With User selected, the prompt settles near the top and the assistant response fills in below it." },
  { id: "anchor-2-user", role: "user", text: "What changes when assistant messages are the anchor?" },
  { id: "anchor-2-assistant", role: "assistant", text: "Now each assistant response is the item MessageScroller keeps in view. This is useful when the reply is the moment you want readers to land on after each turn." },
  { id: "anchor-3-user", role: "user", text: "Can I switch roles and keep adding turns?" },
  { id: "anchor-3-assistant", role: "assistant", text: "Yes. The next appended message with the selected role becomes the anchor, so you can compare user and assistant anchoring without resetting the demo." },
];

static const ROLES: { value: AnchorRole; label: string }[] = [
  { value: "user", label: "User" },
  { value: "assistant", label: "Assistant" },
];

<let/anchorRole=("user" as AnchorRole)/>
<let/messages=([] as ChatMessage[])/>
<let/messageIndex=0/>
<const/nextMessage=SCRIPT[messageIndex]/>

<const/send=() => {
  if (!nextMessage) return;
  messages = [...messages, nextMessage];
  messageIndex += 1;
}/>

<const/reset=() => {
  messages = [];
  messageIndex = 0;
}/>

<const/onRoleChange=(next: string[]) => {
  const value = next[0];
  if (value === "user" || value === "assistant") {
    anchorRole = value;
    reset();
  }
}/>

<div class="relative flex flex-col gap-4">
  <Card class="mx-auto h-140 w-full max-w-sm gap-0">
    <CardHeader class="border-b">
      <CardTitle>Anchoring Turns</CardTitle>
      <CardDescription>Choose which role settles near the top edge.</CardDescription>
      <CardAction>
        <Button type="button" variant="outline" size="icon" aria-label="Reset anchored turns" disabled=(messages.length === 0) onClick=reset>
          <Icon name="RotateCwIcon"/>
        </Button>
      </CardAction>
    </CardHeader>
    <CardContent class="min-h-0 flex-1 overflow-hidden p-0">
      <if=(messages.length === 0)>
        <Empty class="h-full">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <Icon name="MessageCircleIcon"/>
            </EmptyMedia>
            <EmptyTitle>No anchored messages yet</EmptyTitle>
            <EmptyDescription>Send the first message to see the selected role anchor.</EmptyDescription>
          </EmptyHeader>
        </Empty>
      </if>
      <else>
        <MessageScrollerProvider|controller|>
          <MessageScroller controller=controller>
            <MessageScrollerViewport controller=controller>
              <MessageScrollerContent controller=controller class="p-4">
                <for|message| of=messages by=(message) => message.id>
                  <MessageScrollerItem controller=controller messageId=message.id scrollAnchor=(message.role === anchorRole)>
                    <Message align=(message.role === "user" ? "end" : "start")>
                      <MessageContent>
                        <Bubble variant=(message.role === "user" ? "muted" : "ghost")>
                          <BubbleContent class="space-y-2">
                            <p class="whitespace-pre-wrap">${message.text}</p>
                          </BubbleContent>
                        </Bubble>
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                </for>
              </MessageScrollerContent>
            </MessageScrollerViewport>
            <MessageScrollerButton controller=controller/>
          </MessageScroller>
        </MessageScrollerProvider>
      </else>
    </CardContent>
    <CardFooter>
      <ToggleGroup
        aria-label="Select scroll anchor role"
        items=ROLES
        value=[anchorRole]
        valueChange=onRoleChange
      />
      <Button type="button" size="icon" class="ml-auto" disabled=(!nextMessage) onClick=send>
        <Icon name="ArrowUpIcon"/>
        <span class="sr-only">Send Message</span>
      </Button>
    </CardFooter>
  </Card>
  <div class="mx-auto max-w-xs px-0.5 text-center text-xs text-muted-foreground">
    Toggle the anchor role, then send messages to compare where turns settle.
  </div>
</div>

import MessageScrollerProvider from "@marko-ui/shadcn/ui/message-scroller/message-scroller-provider.marko";
import MessageScroller from "@marko-ui/shadcn/ui/message-scroller/message-scroller.marko";
import MessageScrollerViewport from "@marko-ui/shadcn/ui/message-scroller/viewport.marko";
import MessageScrollerContent from "@marko-ui/shadcn/ui/message-scroller/content.marko";
import MessageScrollerItem from "@marko-ui/shadcn/ui/message-scroller/item.marko";
import MessageScrollerButton from "@marko-ui/shadcn/ui/message-scroller/button.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardHeader from "@marko-ui/shadcn/ui/card/header.marko";
import CardTitle from "@marko-ui/shadcn/ui/card/title.marko";
import CardDescription from "@marko-ui/shadcn/ui/card/description.marko";
import CardAction from "@marko-ui/shadcn/ui/card/action.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import CardFooter from "@marko-ui/shadcn/ui/card/footer.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";
import Marker from "@marko-ui/shadcn/ui/marker/marker.marko";
import MarkerContent from "@marko-ui/shadcn/ui/marker/content.marko";
import Message from "@marko-ui/shadcn/ui/message/message.marko";
import MessageContent from "@marko-ui/shadcn/ui/message/content.marko";
import MessageHeader from "@marko-ui/shadcn/ui/message/header.marko";
import Bubble from "@marko-ui/shadcn/ui/bubble/bubble.marko";
import BubbleContent from "@marko-ui/shadcn/ui/bubble/bubble-content.marko";
import Tooltip from "@marko-ui/shadcn/ui/tooltip/tooltip.marko";

static const CURRENT_USER = "Grace";

export type GroupChatItem =
  | { id: string; type: "event"; text: string; scrollAnchor?: boolean }
  | { id: string; type: "message"; sender: string; role: "assistant" | "participant"; text: string; scrollAnchor?: boolean };

static const INITIAL_ITEMS: GroupChatItem[] = [
  { id: "group-1", type: "message", sender: "Grace", role: "participant", text: "@mary, the astrophage line keeps matching Venus energy output. Can you check my math?" },
  { id: "group-2", type: "message", sender: "Mary (Agent)", role: "assistant", text: "Yes. Confirmed. The curve points to a microorganism harvesting stellar energy and breeding near carbon dioxide. If @rocky agrees, this is the clue we need." },
  { id: "group-3", type: "message", sender: "Grace", role: "participant", text: "ping @rocky", scrollAnchor: true },
];

static const ROCKY_MARKER: GroupChatItem = { id: "group-4", type: "event", text: "Rocky has joined the chat", scrollAnchor: true };
static const ROCKY_MESSAGE: GroupChatItem = { id: "group-5", type: "message", sender: "Rocky", role: "participant", text: "Amaze. Astrophage eats light, makes heat, goes to carbon dioxide. Rocky has fuel model. Grace is smart." };

<let/rockyTurn=("idle" as "idle" | "marker" | "message")/>
<const/items=(
  rockyTurn === "message" ? [...INITIAL_ITEMS, ROCKY_MARKER, ROCKY_MESSAGE]
  : rockyTurn === "marker" ? [...INITIAL_ITEMS, ROCKY_MARKER]
  : INITIAL_ITEMS
)/>
<const/buttonLabel=(rockyTurn === "idle" ? "Add Rocky" : "Send Message as Rocky")/>
<const/isComplete=(rockyTurn === "message")/>

<const/reset=() => { rockyTurn = "idle"; }/>
<const/advance=() => { rockyTurn = rockyTurn === "idle" ? "marker" : "message"; }/>

<MessageScrollerProvider|controller|>
  <div class="relative flex flex-col gap-4">
    <Card class="mx-auto h-140 w-full max-w-sm gap-0">
      <CardHeader class="gap-1 border-b">
        <CardTitle>Group Chat</CardTitle>
        <CardDescription>
          A group chat with several participants and an assistant. The Marker is marked as a turn.
        </CardDescription>
        <CardAction>
          <Tooltip>
            <@trigger|props|>
              <Button ...props type="button" variant="outline" size="icon" aria-label="Reset conversation" disabled=(rockyTurn === "idle") onClick=reset>
                <Icon name="RotateCwIcon"/>
              </Button>
            </@trigger>
            Reset
          </Tooltip>
        </CardAction>
      </CardHeader>
      <CardContent class="min-h-0 flex-1 p-0">
        <MessageScroller controller=controller>
          <MessageScrollerViewport controller=controller>
            <MessageScrollerContent controller=controller class="p-4">
              <for|item| of=items by=(item) => item.id>
                <if=(item.type === "message")>
                  <MessageScrollerItem controller=controller messageId=item.id scrollAnchor=item.scrollAnchor>
                    <Message align=(item.sender === CURRENT_USER ? "end" : "start")>
                      <MessageContent>
                        <if=(item.sender !== CURRENT_USER)>
                          <MessageHeader>${item.sender}</MessageHeader>
                        </if>
                        <Bubble variant=(item.sender === CURRENT_USER ? "muted" : item.role === "assistant" ? "ghost" : "tinted")>
                          <BubbleContent>${item.text}</BubbleContent>
                        </Bubble>
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                </if>
                <else>
                  <MessageScrollerItem controller=controller scrollAnchor=(item.scrollAnchor ?? false)>
                    <Marker variant="separator">
                      <MarkerContent>${item.text}</MarkerContent>
                    </Marker>
                  </MessageScrollerItem>
                </else>
              </for>
            </MessageScrollerContent>
          </MessageScrollerViewport>
          <MessageScrollerButton controller=controller/>
        </MessageScroller>
      </CardContent>
      <CardFooter class="flex flex-col items-center gap-2 border-t">
        <Button type="button" disabled=isComplete onClick=advance class="w-full" variant="secondary">
          ${buttonLabel}
        </Button>
        <p class="text-xs text-muted-foreground">
          <if=(rockyTurn === "idle")>This will create a marker and make it the anchor</if>
          <else>Now send Rocky's reply into the conversation</else>
        </p>
      </CardFooter>
    </Card>
    <div class="mx-auto max-w-sm px-0.5 text-center text-xs text-balance text-muted-foreground">
      When a user joins, a marker is created. scrollAnchor on the marker marks it as the next turn
    </div>
  </div>
</MessageScrollerProvider>

import MessageScrollerProvider from "@marko-ui/shadcn/ui/message-scroller/message-scroller-provider.marko";
import MessageScroller from "@marko-ui/shadcn/ui/message-scroller/message-scroller.marko";
import MessageScrollerViewport from "@marko-ui/shadcn/ui/message-scroller/viewport.marko";
import MessageScrollerContent from "@marko-ui/shadcn/ui/message-scroller/content.marko";
import MessageScrollerItem from "@marko-ui/shadcn/ui/message-scroller/item.marko";
import MessageScrollerButton from "@marko-ui/shadcn/ui/message-scroller/button.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardHeader from "@marko-ui/shadcn/ui/card/header.marko";
import CardTitle from "@marko-ui/shadcn/ui/card/title.marko";
import CardDescription from "@marko-ui/shadcn/ui/card/description.marko";
import CardAction from "@marko-ui/shadcn/ui/card/action.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import CardFooter from "@marko-ui/shadcn/ui/card/footer.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";
import Message from "@marko-ui/shadcn/ui/message/message.marko";
import MessageContent from "@marko-ui/shadcn/ui/message/content.marko";
import Bubble from "@marko-ui/shadcn/ui/bubble/bubble.marko";
import BubbleContent from "@marko-ui/shadcn/ui/bubble/bubble-content.marko";
import Tooltip from "@marko-ui/shadcn/ui/tooltip/tooltip.marko";
import Slider from "@marko-ui/shadcn/ui/slider/slider.marko";

static const DEFAULT_PEEK = 64;

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  text: string;
}

static const SCRIPT: ChatMessage[] = [
  { id: "prev-1-user", role: "user", text: "I'm building a chat for our app and the scroll behavior is driving me nuts. Every time the AI streams a reply, the whole thread jumps around." },
  { id: "prev-1-assistant", role: "assistant", text: "That's the classic streaming scroll problem. Wrap your message list in MessageScroller and turn on autoScroll — the viewport pins to the bottom as tokens arrive." },
  { id: "prev-2-user", role: "user", text: "Okay, but when someone sends a new message the view still feels jarring — like the whole conversation reloads from the top." },
  { id: "prev-2-assistant", role: "assistant", text: "MessageScrollerItem fixes that with turn anchoring. It also leaves a small peek of the previous exchange visible above the anchor, so context isn't lost." },
];

<let/messages=(SCRIPT.slice(0, 2) as ChatMessage[])/>
<let/peek=DEFAULT_PEEK/>
<let/busy=false/>
<let/providerKey=0/>
<const/nextMessage=SCRIPT[messages.length]/>

<const/send=() => {
  if (!nextMessage || busy) return;
  const outgoing = nextMessage;
  messages = [...messages, outgoing];
  if (outgoing.role === "user") {
    busy = true;
    setTimeout(() => {
      const reply = SCRIPT[messages.length];
      if (reply) messages = [...messages, reply];
      busy = false;
    }, 700);
  }
}/>

<const/reset=() => {
  messages = SCRIPT.slice(0, 2);
  peek = DEFAULT_PEEK;
  providerKey += 1;
  busy = false;
}/>

<for|generation| of=[providerKey] by=(value) => String(value)>
  <MessageScrollerProvider|controller| scrollMargin=24 scrollPreviousItemPeek=peek>
    <div class="relative flex flex-col gap-4">
      <Card class="mx-auto h-140 w-full max-w-sm gap-0">
        <CardHeader class="gap-1 border-b">
          <CardTitle>Keeping Context Visible</CardTitle>
          <CardDescription>New turns keep part of the previous reply in view.</CardDescription>
          <CardAction>
            <Tooltip>
              <@trigger|props|>
                <Button type="button" ...props variant="outline" size="icon" aria-label="Reset context example" disabled=busy onClick=reset>
                  <Icon name="RotateCwIcon"/>
                </Button>
              </@trigger>
              Reset
            </Tooltip>
          </CardAction>
        </CardHeader>
        <CardContent class="flex-1 overflow-hidden p-0">
          <MessageScroller controller=controller>
            <MessageScrollerViewport controller=controller>
              <MessageScrollerContent controller=controller aria-busy=(busy ? "true" : "false") class="p-4">
                <for|message| of=messages by=(message) => message.id>
                  <MessageScrollerItem controller=controller messageId=message.id scrollAnchor=(message.role === "user")>
