          <EmptyHeader>
            <EmptyMedia variant="icon">
              <Icon name="MessageCircleIcon"/>
            </EmptyMedia>
            <EmptyTitle>No Messages Yet</EmptyTitle>
            <EmptyDescription>Click the button below to send the first message.</EmptyDescription>
          </EmptyHeader>
        </Empty>
      </if>
      <else>
        <MessageScrollerProvider|controller|>
          <MessageScroller controller=controller>
            <MessageScrollerViewport controller=controller>
              <MessageScrollerContent controller=controller aria-busy=(busy ? "true" : "false") class="p-4">
                <for|message| of=messages by=(message) => message.id>
                  <MessageScrollerItem
                    controller=controller
                    messageId=message.id
                    class=("transition-[transform,opacity] duration-300 ease-out " + (message.id === enteringId ? preset.enterClass : preset.restClass))
                  >
                    <Message align=(message.role === "user" ? "end" : "start")>
                      <MessageContent>
                        <Bubble variant=(message.role === "user" ? "muted" : "ghost")>
                          <BubbleContent class="space-y-2">
                            <p class="whitespace-pre-wrap">${message.text}</p>
                          </BubbleContent>
                        </Bubble>
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                </for>
              </MessageScrollerContent>
            </MessageScrollerViewport>
            <MessageScrollerButton controller=controller/>
          </MessageScroller>
        </MessageScrollerProvider>
      </else>
    </CardContent>
    <CardFooter class="border-t">
      <Select
        items=PRESETS
        value=[presetId]
        placeholder="Animation preset"
        valueChange=(value: string[]) => { presetId = value[0] ?? "fade"; }
      />
      <Button type="button" size="icon" class="ml-auto" disabled=(!nextMessage || busy) onClick=send>
        <Icon name="ArrowUpIcon"/>
        <span class="sr-only">Send Message</span>
      </Button>
    </CardFooter>
  </Card>
  <div class="mx-auto max-w-sm px-0.5 text-center text-xs text-balance text-muted-foreground">
    Select an animation then click send to see it in action.
  </div>
</div>

